/* generated by scripts/build-glossary.js from glossary.json: do not edit */
globalThis.JargonLens = Object.assign(globalThis.JargonLens || {}, { BUILTIN: [{"term":"OKR","meaning":"Objectives and Key Results: a goal-setting method where one ambitious objective is paired with a few measurable results."},{"term":"KPI","meaning":"Key Performance Indicator: a number the team tracks to tell whether it is doing well."},{"term":"P0","meaning":"Highest priority. Drop other work: something critical is broken or blocking."},{"term":"P1","meaning":"Very high priority. Must be handled soon, usually the same day or week."},{"term":"P2","meaning":"Medium priority. Should be done, but can be scheduled."},{"term":"P3","meaning":"Low priority. Nice to have, handled when there is time."},{"term":"SEV1","meaning":"Severity 1: the most serious kind of incident, usually a major outage affecting many users."},{"term":"SLA","meaning":"Service Level Agreement: a promise to customers about uptime or response time, often with penalties."},{"term":"SLO","meaning":"Service Level Objective: the internal reliability target a team aims to meet, such as 99.9% uptime."},{"term":"SLI","meaning":"Service Level Indicator: the actual measurement (latency, error rate) used to check an SLO."},{"term":"ETA","meaning":"Estimated Time of Arrival: when something is expected to be done."},{"term":"EOD","meaning":"End of Day."},{"term":"EOW","meaning":"End of Week."},{"term":"EOM","meaning":"End of Month."},{"term":"COB","meaning":"Close of Business: the end of the working day."},{"term":"OOO","meaning":"Out of Office."},{"term":"WFH","meaning":"Working From Home."},{"term":"PTO","meaning":"Paid Time Off: vacation or leave."},{"term":"LGTM","meaning":"Looks Good To Me: a reviewer's approval."},{"term":"PR","meaning":"Pull Request: a proposed code change waiting for review before it is merged."},{"term":"MR","meaning":"Merge Request: GitLab's name for a pull request."},{"term":"FYI","meaning":"For Your Information: no action needed, just so you know."},{"term":"IMO","meaning":"In My Opinion."},{"term":"AFAIK","meaning":"As Far As I Know."},{"term":"TBD","meaning":"To Be Decided."},{"term":"TBH","meaning":"To Be Honest."},{"term":"ASAP","meaning":"As Soon As Possible."},{"term":"RFC","meaning":"Request For Comments: a written proposal shared so others can give feedback before a decision."},{"term":"PRD","meaning":"Product Requirements Document: describes what a feature should do and why."},{"term":"MVP","meaning":"Minimum Viable Product: the smallest version that is still useful enough to learn from."},{"term":"POC","meaning":"Proof Of Concept: a quick prototype to show an idea can work."},{"term":"ROI","meaning":"Return On Investment: what you get back compared with what you put in."},{"term":"ARR","meaning":"Annual Recurring Revenue: yearly subscription revenue."},{"term":"MRR","meaning":"Monthly Recurring Revenue: monthly subscription revenue."},{"term":"B2B","meaning":"Business to Business: selling to other companies."},{"term":"B2C","meaning":"Business to Consumer: selling directly to individuals."},{"term":"SaaS","meaning":"Software as a Service: software you subscribe to and use online."},{"term":"CI/CD","meaning":"Continuous Integration / Continuous Delivery: automation that tests and ships code changes."},{"term":"SRE","meaning":"Site Reliability Engineering: the practice (or team) that keeps services reliable."},{"term":"RCA","meaning":"Root Cause Analysis: figuring out the real reason something failed."},{"term":"MTTR","meaning":"Mean Time To Recovery: the average time it takes to fix an outage."},{"term":"MTTD","meaning":"Mean Time To Detect: the average time it takes to notice a problem."},{"term":"RACI","meaning":"Responsible, Accountable, Consulted, Informed: a chart that clarifies who does what on a task."},{"term":"DRI","meaning":"Directly Responsible Individual: the one person who owns a task or decision."},{"term":"ICP","meaning":"Ideal Customer Profile: the type of customer a company most wants to win."},{"term":"GTM","meaning":"Go To Market: the plan for launching and selling a product."},{"term":"NPS","meaning":"Net Promoter Score: a survey score for how likely customers are to recommend you."},{"term":"CSAT","meaning":"Customer Satisfaction score."},{"term":"QBR","meaning":"Quarterly Business Review: a meeting that reviews results from the last quarter."},{"term":"WIP","meaning":"Work In Progress: not finished yet."},{"term":"MoM","meaning":"Month over Month: comparing this month to the previous one."},{"term":"YoY","meaning":"Year over Year: comparing this year to the previous one."},{"term":"PIP","meaning":"Performance Improvement Plan: a formal plan for an employee to improve, often a warning step."},{"term":"TAM","meaning":"Total Addressable Market: the full amount of demand for a product."},{"term":"SOW","meaning":"Statement of Work: a document that defines the scope, deliverables and timeline of a project."},{"term":"NDA","meaning":"Non-Disclosure Agreement: a contract to keep information confidential."},{"term":"SSO","meaning":"Single Sign-On: one login that works across several apps."},{"term":"UAT","meaning":"User Acceptance Testing: final testing by real users before release."},{"term":"SOP","meaning":"Standard Operating Procedure: a written step-by-step process."},{"term":"HRBP","meaning":"HR Business Partner: the HR person who supports a specific team."},{"term":"standup","meaning":"A short daily meeting where everyone says what they did, what they will do and what blocks them."},{"term":"retro","meaning":"Retrospective: a meeting after a sprint or project about what went well and what to improve."},{"term":"sprint","meaning":"A fixed work period, usually one to two weeks, in which a team commits to a set of tasks."},{"term":"backlog","meaning":"The list of work waiting to be done, in priority order."},{"term":"blocker","meaning":"Something that prevents progress until it is resolved."},{"term":"bandwidth","meaning":"How much time or capacity someone has for more work."},{"term":"circle back","meaning":"Return to this topic later."},{"term":"deep dive","meaning":"A thorough, detailed look at one topic."},{"term":"low-hanging fruit","meaning":"Easy wins that give good results for little effort."},{"term":"move the needle","meaning":"Make a noticeable difference to the results."},{"term":"synergy","meaning":"Two things working together to get more than the sum of their parts (often used vaguely)."},{"term":"stakeholder","meaning":"Anyone affected by or interested in a project: customers, managers, other teams."},{"term":"action item","meaning":"A specific task someone has agreed to do after a meeting."},{"term":"take this offline","meaning":"Discuss this outside the current meeting or thread."},{"term":"touch base","meaning":"Briefly check in with someone."},{"term":"north star","meaning":"The single most important goal or metric guiding decisions."},{"term":"runway","meaning":"How many months a company can operate before it runs out of money."},{"term":"burn rate","meaning":"How fast a company is spending its cash, usually per month."},{"term":"headcount","meaning":"The number of people on a team or approved to hire."},{"term":"on-call","meaning":"Being the person who must respond if something breaks outside normal hours."},{"term":"dogfooding","meaning":"Using your own product internally to find problems before customers do."},{"term":"tech debt","meaning":"Shortcuts in code that make future changes slower until they are cleaned up."},{"term":"ship it","meaning":"Release it: it is ready to go out."},{"term":"ping","meaning":"Send a quick message to get someone's attention."},{"term":"parking lot","meaning":"A list of off-topic points saved to discuss later."},{"term":"boil the ocean","meaning":"Attempt something far too big or complicated."},{"term":"table stakes","meaning":"The minimum features or standards required to compete."}] });
